<template><div class="share-backdrop" @click.self="$emit('close')"><section role="dialog" aria-modal="true" aria-label="Share document with portal account"><header><h3>Share a document copy</h3><button @click="$emit('close')">Close</button></header><p>Review the file before sharing. A paper packet can include another guardian’s private answers; share only the copy appropriate for this recipient.</p><p v-if="error" role="alert">{{error}}</p><p v-if="loading">Loading recipients…</p><p v-else-if="!recipients.length">No linked accounts currently have document access.</p><template v-else><label>Recipient<select v-model="recipientId" @change="reviewed=false"><option value="">Choose an account</option><option v-for="r in recipients" :key="r.id" :value="r.id">{{r.name}}{{r.shared?' · shared':''}}</option></select></label><label v-if="!selected?.shared"><input v-model="reviewed" type="checkbox"/> I reviewed this file and verified that this account is authorized to receive its contents.</label><button :disabled="busy||!recipientId||(!selected?.shared&&(!shareable||!reviewed))" @click="save">{{selected?.shared?'Revoke portal access':'Share reviewed copy'}}</button><p v-if="!shareable">This file cannot be newly shared until it is available and its scan is complete.</p></template></section></div></template>
<script setup>
import {computed,ref,onMounted} from 'vue';import api from '../../services/api';
const props=defineProps({documentId:Number});defineEmits(['close']);const recipients=ref([]),recipientId=ref(''),reviewed=ref(false),shareable=ref(false),loading=ref(false),busy=ref(false),error=ref('');const selected=computed(()=>recipients.value.find(r=>r.id===recipientId.value));
async function load(){loading.value=true;error.value='';try{const{data}=await api.get(`/phi-documents/${props.documentId}/portal-shares`);recipients.value=data.recipients;shareable.value=data.shareable;}catch(e){error.value=e.response?.status<500?e.response?.data?.error?.message:'Document sharing could not be loaded.';}finally{loading.value=false;}}
async function save(){busy.value=true;error.value='';try{await api.put(`/phi-documents/${props.documentId}/portal-shares`,{recipientId:recipientId.value,shared:!selected.value.shared,reviewed:reviewed.value});await load();reviewed.value=false;}catch(e){error.value=e.response?.status<500?e.response?.data?.error?.message:'Document sharing could not be saved.';}finally{busy.value=false;}}
onMounted(load);
</script>
<style scoped>.share-backdrop{position:fixed;inset:0;background:#142e4c80;z-index:10000;display:grid;place-items:center;padding:20px}.share-backdrop section{max-width:600px;max-height:85vh;overflow:auto;background:white;color:#173451;padding:24px;border-radius:14px;display:grid;gap:16px}.share-backdrop header{display:flex;justify-content:space-between;gap:20px}.share-backdrop label{display:block;line-height:1.6}.share-backdrop select{display:block;padding:10px;width:100%}.share-backdrop button{font:inherit;padding:10px 14px;border:1px solid #bbcede;border-radius:8px;cursor:pointer}.share-backdrop p{line-height:1.6;margin:0}[role=alert]{color:#a12727}</style>
